    best_next = None
    best_score = None
    for dx, dy, nx, ny in moves:
        score = None
        for rx, ry in resources:
            sd = dist(nx, ny, rx, ry)
            od = dist(ox, oy, rx, ry)
            margin = od - sd
            # If we can beat opponent, prioritize; otherwise avoid "far" from opponent's nearest.
            front = 1 if sd <= od else 0
